from pathlib import Path
import shutil

BOARD_RS = 'use crate::{ValidationReport, load_issues, load_reviews};\nuse serde::{Deserialize, Serialize};\nuse std::collections::{BTreeMap, BTreeSet};\nuse std::fs;\nuse std::path::{Path, PathBuf};\n\npub const BOARD_SCHEMA_V0: &str = "allodium.board/v0";\npub const BOARD_FIELD_SCHEMA_V0: &str = "allodium.board-field/v0";\npub const BOARD_ITEM_SCHEMA_V0: &str = "allodium.board-item/v0";\npub const BOARD_VIEW_SCHEMA_V0: &str = "allodium.board-view/v0";\n\n#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]\npub struct BoardRecord {\n    pub schema: String,\n    pub id: String,\n    pub title: String,\n    #[serde(default)]\n    pub description: String,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]\npub struct BoardFieldOption {\n    pub id: String,\n    pub name: String,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]\npub struct BoardFieldRecord {\n    pub schema: String,\n    pub id: String,\n    pub name: String,\n    pub kind: String,\n    #[serde(default)]\n    pub options: Vec<BoardFieldOption>,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]\npub struct BoardItemRecord {\n    pub schema: String,\n    pub object: String,\n    #[serde(default)]\n    pub values: BTreeMap<String, toml::Value>,\n}\n\n#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]\npub struct BoardViewRecord {\n    pub schema: String,\n    pub id: String,\n    pub name: String,\n    pub layout: String,\n    #[serde(default, skip_serializing_if = "Option::is_none")]\n    pub group_by: Option<String>,\n    #[serde(default, skip_serializing_if = "Option::is_none")]\n    pub start_field: Option<String>,\n    #[serde(default, skip_serializing_if = "Option::is_none")]\n    pub end_field: Option<String>,\n}\n\n#[derive(Debug, Clone, PartialEq, Eq)]\npub struct CanonicalBoardField {\n    pub record: BoardFieldRecord,\n    pub path: PathBuf,\n}\n\n#[derive(Debug, Clone, PartialEq)]\npub struct CanonicalBoardItem {\n    pub record: BoardItemRecord,\n    pub path: PathBuf,\n}\n\n#[derive(Debug, Clone, PartialEq, Eq)]\npub struct CanonicalBoardView {\n    pub record: BoardViewRecord,\n    pub path: PathBuf,\n}\n\n#[derive(Debug, Clone, PartialEq)]\npub struct CanonicalBoard {\n    pub record: BoardRecord,\n    pub directory: PathBuf,\n    pub fields: Vec<CanonicalBoardField>,\n    pub items: Vec<CanonicalBoardItem>,\n    pub views: Vec<CanonicalBoardView>,\n}\n\npub fn load_boards(root: impl AsRef<Path>) -> Result<Vec<CanonicalBoard>, String> {\n    let boards_dir = root.as_ref().join(".project/boards");\n    if !boards_dir.exists() {\n        return Ok(Vec::new());\n    }\n    if !boards_dir.is_dir() {\n        return Err(format!("{}: expected a directory", boards_dir.display()));\n    }\n\n    let mut entries = fs::read_dir(&boards_dir)\n        .map_err(|error| format!("{}: {error}", boards_dir.display()))?\n        .collect::<Result<Vec<_>, _>>()\n        .map_err(|error| format!("{}: {error}", boards_dir.display()))?;\n    entries.sort_by_key(|entry| entry.file_name());\n\n    let mut boards = Vec::new();\n    for entry in entries {\n        let directory = entry.path();\n        if !directory.is_dir() {\n            continue;\n        }\n\n        let record_path = directory.join("board.toml");\n        let record: BoardRecord = read_toml(&record_path)?;\n        let fields = load_fields(&directory.join("fields"))?;\n        let items = load_items(&directory.join("items"))?;\n        let views = load_views(&directory.join("views"))?;\n\n        boards.push(CanonicalBoard {\n            record,\n            directory,\n            fields,\n            items,\n            views,\n        });\n    }\n\n    boards.sort_by(|left, right| left.record.id.cmp(&right.record.id));\n    Ok(boards)\n}\n\npub(crate) fn validate_boards(root: &Path, report: &mut ValidationReport) {\n    let boards = match load_boards(root) {\n        Ok(boards) => boards,\n        Err(error) => {\n            report.errors.push(error);\n            return;\n        }\n    };\n\n    let mut canonical_objects = BTreeSet::new();\n    match load_issues(root) {\n        Ok(issues) => {\n            canonical_objects.extend(issues.into_iter().map(|issue| issue.record.id));\n        }\n        Err(error) => report.errors.push(error),\n    }\n    match load_reviews(root) {\n        Ok(reviews) => {\n            canonical_objects.extend(reviews.into_iter().map(|review| review.record.id));\n        }\n        Err(error) => report.errors.push(error),\n    }\n\n    let mut board_ids = BTreeSet::new();\n    for board in boards {\n        validate_board(&board, &canonical_objects, report);\n        if !board_ids.insert(board.record.id.clone()) {\n            report.errors.push(format!(\n                "{}: duplicate board id {:?}",\n                board.directory.display(),\n                board.record.id\n            ));\n        }\n    }\n}\n\nfn validate_board(\n    board: &CanonicalBoard,\n    canonical_objects: &BTreeSet<String>,\n    report: &mut ValidationReport,\n) {\n    let record_path = board.directory.join("board.toml");\n    let expected_id = board\n        .directory\n        .file_name()\n        .and_then(|name| name.to_str())\n        .unwrap_or_default();\n\n    if board.record.schema != BOARD_SCHEMA_V0 {\n        report.errors.push(format!(\n            "{}: unsupported schema {:?}; expected {:?}",\n            record_path.display(),\n            board.record.schema,\n            BOARD_SCHEMA_V0\n        ));\n    }\n    if board.record.id != expected_id {\n        report.errors.push(format!(\n            "{}: id {:?} must match directory {:?}",\n            record_path.display(),\n            board.record.id,\n            expected_id\n        ));\n    }\n    if board.record.title.trim().is_empty() {\n        report.errors.push(format!(\n            "{}: title must not be empty",\n            record_path.display()\n        ));\n    }\n\n    let mut fields = BTreeMap::new();\n    for field in &board.fields {\n        validate_field(field, report);\n        if fields.insert(field.record.id.clone(), field).is_some() {\n            report.errors.push(format!(\n                "{}: duplicate field id {:?}",\n                field.path.display(),\n                field.record.id\n            ));\n        }\n    }\n\n    let mut objects = BTreeSet::new();\n    for item in &board.items {\n        validate_item(item, &fields, canonical_objects, report);\n        if !objects.insert(item.record.object.clone()) {\n            report.errors.push(format!(\n                "{}: duplicate board item for canonical object {:?}",\n                item.path.display(),\n                item.record.object\n            ));\n        }\n    }\n\n    let mut views = BTreeSet::new();\n    for view in &board.views {\n        validate_view(view, &fields, report);\n        if !views.insert(view.record.id.clone()) {\n            report.errors.push(format!(\n                "{}: duplicate view id {:?}",\n                view.path.display(),\n                view.record.id\n            ));\n        }\n    }\n}\n\nfn validate_field(field: &CanonicalBoardField, report: &mut ValidationReport) {\n    let expected_id = field\n        .path\n        .file_stem()\n        .and_then(|name| name.to_str())\n        .unwrap_or_default();\n\n    if field.record.schema != BOARD_FIELD_SCHEMA_V0 {\n        report.errors.push(format!(\n            "{}: unsupported schema {:?}; expected {:?}",\n            field.path.display(),\n            field.record.schema,\n            BOARD_FIELD_SCHEMA_V0\n        ));\n    }\n    if field.record.id != expected_id {\n        report.errors.push(format!(\n            "{}: id {:?} must match filename stem {:?}",\n            field.path.display(),\n            field.record.id,\n            expected_id\n        ));\n    }\n    if field.record.name.trim().is_empty() {\n        report.errors.push(format!(\n            "{}: name must not be empty",\n            field.path.display()\n        ));\n    }\n\n    if !matches!(\n        field.record.kind.as_str(),\n        "text" | "number" | "date" | "single_select"\n    ) {\n        report.errors.push(format!(\n            "{}: kind must be text, number, date, or single_select",\n            field.path.display()\n        ));\n    }\n\n    if field.record.kind == "single_select" {\n        if field.record.options.is_empty() {\n            report.errors.push(format!(\n                "{}: single_select fields require at least one option",\n                field.path.display()\n            ));\n        }\n        let mut option_ids = BTreeSet::new();\n        for option in &field.record.options {\n            if option.id.trim().is_empty() || option.name.trim().is_empty() {\n                report.errors.push(format!(\n                    "{}: single_select option id and name must not be empty",\n                    field.path.display()\n                ));\n            }\n            if !option_ids.insert(option.id.clone()) {\n                report.errors.push(format!(\n                    "{}: duplicate single_select option id {:?}",\n                    field.path.display(),\n                    option.id\n                ));\n            }\n        }\n    } else if !field.record.options.is_empty() {\n        report.errors.push(format!(\n            "{}: only single_select fields may declare options",\n            field.path.display()\n        ));\n    }\n}\n\nfn validate_item(\n    item: &CanonicalBoardItem,\n    fields: &BTreeMap<String, &CanonicalBoardField>,\n    canonical_objects: &BTreeSet<String>,\n    report: &mut ValidationReport,\n) {\n    let expected_object = item\n        .path\n        .file_stem()\n        .and_then(|name| name.to_str())\n        .unwrap_or_default();\n\n    if item.record.schema != BOARD_ITEM_SCHEMA_V0 {\n        report.errors.push(format!(\n            "{}: unsupported schema {:?}; expected {:?}",\n            item.path.display(),\n            item.record.schema,\n            BOARD_ITEM_SCHEMA_V0\n        ));\n    }\n    if item.record.object != expected_object {\n        report.errors.push(format!(\n            "{}: object {:?} must match filename stem {:?}",\n            item.path.display(),\n            item.record.object,\n            expected_object\n        ));\n    }\n    if !canonical_objects.contains(&item.record.object) {\n        report.errors.push(format!(\n            "{}: object {:?} does not reference an existing canonical issue or review",\n            item.path.display(),\n            item.record.object\n        ));\n    }\n\n    for (field_id, value) in &item.record.values {\n        let Some(field) = fields.get(field_id) else {\n            report.errors.push(format!(\n                "{}: value references unknown field {:?}",\n                item.path.display(),\n                field_id\n            ));\n            continue;\n        };\n        validate_value(item, field, value, report);\n    }\n}\n\nfn validate_value(\n    item: &CanonicalBoardItem,\n    field: &CanonicalBoardField,\n    value: &toml::Value,\n    report: &mut ValidationReport,\n) {\n    let valid = match field.record.kind.as_str() {\n        "text" => value.as_str().is_some(),\n        "number" => value.as_integer().is_some() || value.as_float().is_some(),\n        "date" => value.as_str().is_some_and(valid_calendar_date),\n        "single_select" => value.as_str().is_some_and(|selected| {\n            field\n                .record\n                .options\n                .iter()\n                .any(|option| option.id == selected)\n        }),\n        _ => true,\n    };\n\n    if valid {\n        return;\n    }\n\n    let expectation = match field.record.kind.as_str() {\n        "text" => "requires a string value",\n        "number" => "requires an integer or float value",\n        "date" => "requires an ISO 8601 calendar date (YYYY-MM-DD)",\n        "single_select" => "requires a declared option id",\n        _ => "has an unsupported field kind",\n    };\n    report.errors.push(format!(\n        "{}: field {:?} {expectation}",\n        item.path.display(),\n        field.record.id\n    ));\n}\n\nfn validate_view(\n    view: &CanonicalBoardView,\n    fields: &BTreeMap<String, &CanonicalBoardField>,\n    report: &mut ValidationReport,\n) {\n    let expected_id = view\n        .path\n        .file_stem()\n        .and_then(|name| name.to_str())\n        .unwrap_or_default();\n\n    if view.record.schema != BOARD_VIEW_SCHEMA_V0 {\n        report.errors.push(format!(\n            "{}: unsupported schema {:?}; expected {:?}",\n            view.path.display(),\n            view.record.schema,\n            BOARD_VIEW_SCHEMA_V0\n        ));\n    }\n    if view.record.id != expected_id {\n        report.errors.push(format!(\n            "{}: id {:?} must match filename stem {:?}",\n            view.path.display(),\n            view.record.id,\n            expected_id\n        ));\n    }\n    if view.record.name.trim().is_empty() {\n        report.errors.push(format!(\n            "{}: name must not be empty",\n            view.path.display()\n        ));\n    }\n    if !matches!(view.record.layout.as_str(), "table" | "board" | "roadmap") {\n        report.errors.push(format!(\n            "{}: layout must be table, board, or roadmap",\n            view.path.display()\n        ));\n    }\n\n    if view.record.layout == "board" && view.record.group_by.is_none() {\n        report.errors.push(format!(\n            "{}: board views require group_by",\n            view.path.display()\n        ));\n    }\n    if view.record.layout == "roadmap"\n        && view.record.start_field.is_none()\n        && view.record.end_field.is_none()\n    {\n        report.errors.push(format!(\n            "{}: roadmap views require start_field or end_field",\n            view.path.display()\n        ));\n    }\n\n    validate_view_field_ref(view, "group_by", view.record.group_by.as_deref(), fields, false, report);\n    validate_view_field_ref(\n        view,\n        "start_field",\n        view.record.start_field.as_deref(),\n        fields,\n        true,\n        report,\n    );\n    validate_view_field_ref(\n        view,\n        "end_field",\n        view.record.end_field.as_deref(),\n        fields,\n        true,\n        report,\n    );\n}\n\nfn validate_view_field_ref(\n    view: &CanonicalBoardView,\n    property: &str,\n    field_id: Option<&str>,\n    fields: &BTreeMap<String, &CanonicalBoardField>,\n    require_date: bool,\n    report: &mut ValidationReport,\n) {\n    let Some(field_id) = field_id else {\n        return;\n    };\n    let Some(field) = fields.get(field_id) else {\n        report.errors.push(format!(\n            "{}: {property} references unknown field {:?}",\n            view.path.display(),\n            field_id\n        ));\n        return;\n    };\n    if require_date && field.record.kind != "date" {\n        report.errors.push(format!(\n            "{}: {property} field {:?} must have kind date",\n            view.path.display(),\n            field_id\n        ));\n    }\n}\n\nfn load_fields(path: &Path) -> Result<Vec<CanonicalBoardField>, String> {\n    load_toml_files(path, |record, path| CanonicalBoardField { record, path })\n}\n\nfn load_items(path: &Path) -> Result<Vec<CanonicalBoardItem>, String> {\n    load_toml_files(path, |record, path| CanonicalBoardItem { record, path })\n}\n\nfn load_views(path: &Path) -> Result<Vec<CanonicalBoardView>, String> {\n    load_toml_files(path, |record, path| CanonicalBoardView { record, path })\n}\n\nfn load_toml_files<T, U>(\n    path: &Path,\n    make: impl Fn(T, PathBuf) -> U,\n) -> Result<Vec<U>, String>\nwhere\n    T: for<\'de> Deserialize<\'de>,\n{\n    if !path.exists() {\n        return Ok(Vec::new());\n    }\n    if !path.is_dir() {\n        return Err(format!("{}: expected a directory", path.display()));\n    }\n\n    let mut entries = fs::read_dir(path)\n        .map_err(|error| format!("{}: {error}", path.display()))?\n        .collect::<Result<Vec<_>, _>>()\n        .map_err(|error| format!("{}: {error}", path.display()))?;\n    entries.sort_by_key(|entry| entry.file_name());\n\n    let mut records = Vec::new();\n    for entry in entries {\n        let record_path = entry.path();\n        if !record_path.is_file()\n            || record_path.extension().and_then(|value| value.to_str()) != Some("toml")\n        {\n            continue;\n        }\n        let record = read_toml(&record_path)?;\n        records.push(make(record, record_path));\n    }\n    Ok(records)\n}\n\nfn read_toml<T>(path: &Path) -> Result<T, String>\nwhere\n    T: for<\'de> Deserialize<\'de>,\n{\n    let text = fs::read_to_string(path).map_err(|error| format!("{}: {error}", path.display()))?;\n    toml::from_str(&text).map_err(|error| format!("{}: {error}", path.display()))\n}\n\nfn valid_calendar_date(value: &str) -> bool {\n    let bytes = value.as_bytes();\n    if bytes.len() != 10 || bytes[4] != b\'-\' || bytes[7] != b\'-\' {\n        return false;\n    }\n    if bytes\n        .iter()\n        .enumerate()\n        .any(|(index, byte)| index != 4 && index != 7 && !byte.is_ascii_digit())\n    {\n        return false;\n    }\n\n    let year = value[0..4].parse::<u32>().ok();\n    let month = value[5..7].parse::<u32>().ok();\n    let day = value[8..10].parse::<u32>().ok();\n    let (Some(year), Some(month), Some(day)) = (year, month, day) else {\n        return false;\n    };\n    if !(1..=12).contains(&month) || day == 0 {\n        return false;\n    }\n\n    let leap = year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);\n    let max_day = match month {\n        2 if leap => 29,\n        2 => 28,\n        4 | 6 | 9 | 11 => 30,\n        _ => 31,\n    };\n    day <= max_day\n}\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n    use std::time::{SystemTime, UNIX_EPOCH};\n\n    #[test]\n    fn validator_accepts_filesystem_native_board() {\n        let root = test_root("valid");\n        write_board(&root, "active", true);\n\n        let report = crate::validate(&root);\n        assert!(report.is_ok(), "{:?}", report.errors);\n        fs::remove_dir_all(root).unwrap();\n    }\n\n    #[test]\n    fn validator_rejects_dangling_object_and_unknown_select_option() {\n        let root = test_root("bad-item");\n        write_board(&root, "not-an-option", true);\n        let item_path = root.join(".project/boards/board-0001/items/issue-0001.toml");\n        let item = fs::read_to_string(&item_path).unwrap();\n        fs::write(\n            root.join(".project/boards/board-0001/items/issue-9999.toml"),\n            item.replace("object = \\"issue-0001\\"", "object = \\"issue-9999\\""),\n        )\n        .unwrap();\n\n        let report = crate::validate(&root);\n        assert!(!report.is_ok());\n        assert!(\n            report\n                .errors\n                .iter()\n                .any(|error| error.contains("requires a declared option id"))\n        );\n        assert!(\n            report\n                .errors\n                .iter()\n                .any(|error| error.contains("does not reference an existing canonical issue or review"))\n        );\n        fs::remove_dir_all(root).unwrap();\n    }\n\n    #[test]\n    fn validator_rejects_invalid_view_semantics() {\n        let root = test_root("bad-view");\n        write_board(&root, "active", false);\n        fs::write(\n            root.join(".project/boards/board-0001/views/roadmap.toml"),\n            "schema = \\"allodium.board-view/v0\\"\\nid = \\"roadmap\\"\\nname = \\"Roadmap\\"\\nlayout = \\"roadmap\\"\\nend_field = \\"status\\"\\n",\n        )\n        .unwrap();\n\n        let report = crate::validate(&root);\n        assert!(!report.is_ok());\n        assert!(\n            report\n                .errors\n                .iter()\n                .any(|error| error.contains("board views require group_by"))\n        );\n        assert!(\n            report\n                .errors\n                .iter()\n                .any(|error| error.contains("must have kind date"))\n        );\n        fs::remove_dir_all(root).unwrap();\n    }\n\n    fn write_board(root: &Path, status: &str, group_board: bool) {\n        let board = root.join(".project/boards/board-0001");\n        fs::create_dir_all(board.join("fields")).unwrap();\n        fs::create_dir_all(board.join("items")).unwrap();\n        fs::create_dir_all(board.join("views")).unwrap();\n        fs::write(\n            board.join("board.toml"),\n            "schema = \\"allodium.board/v0\\"\\nid = \\"board-0001\\"\\ntitle = \\"Development\\"\\ndescription = \\"Test board\\"\\n",\n        )\n        .unwrap();\n        fs::write(\n            board.join("fields/status.toml"),\n            "schema = \\"allodium.board-field/v0\\"\\nid = \\"status\\"\\nname = \\"Status\\"\\nkind = \\"single_select\\"\\n\\n[[options]]\\nid = \\"active\\"\\nname = \\"Active\\"\\n\\n[[options]]\\nid = \\"done\\"\\nname = \\"Done\\"\\n",\n        )\n        .unwrap();\n        fs::write(\n            board.join("fields/target-date.toml"),\n            "schema = \\"allodium.board-field/v0\\"\\nid = \\"target-date\\"\\nname = \\"Target date\\"\\nkind = \\"date\\"\\n",\n        )\n        .unwrap();\n        fs::write(\n            board.join("items/issue-0001.toml"),\n            format!(\n                "schema = \\"allodium.board-item/v0\\"\\nobject = \\"issue-0001\\"\\n\\n[values]\\nstatus = \\"{status}\\"\\ntarget-date = \\"2026-09-30\\"\\n"\n            ),\n        )\n        .unwrap();\n        fs::write(\n            board.join("views/development.toml"),\n            if group_board {\n                "schema = \\"allodium.board-view/v0\\"\\nid = \\"development\\"\\nname = \\"Development\\"\\nlayout = \\"board\\"\\ngroup_by = \\"status\\"\\n"\n            } else {\n                "schema = \\"allodium.board-view/v0\\"\\nid = \\"development\\"\\nname = \\"Development\\"\\nlayout = \\"board\\"\\n"\n            },\n        )\n        .unwrap();\n    }\n\n    fn test_root(name: &str) -> PathBuf {\n        let nonce = SystemTime::now()\n            .duration_since(UNIX_EPOCH)\n            .unwrap()\n            .as_nanos();\n        let root = std::env::temp_dir().join(format!(\n            "allodium-board-{name}-{}-{nonce}",\n            std::process::id()\n        ));\n        fs::create_dir_all(root.join(".project/issues/issue-0001")).unwrap();\n        fs::create_dir_all(root.join(".project/remotes/github")).unwrap();\n        fs::write(\n            root.join(".project/manifest.toml"),\n            "schema = \\"allodium.project/v0\\"\\nid = \\"test\\"\\nname = \\"Test\\"\\n",\n        )\n        .unwrap();\n        fs::write(\n            root.join(".project/issues/issue-0001/issue.toml"),\n            "schema = \\"allodium.issue/v0\\"\\nid = \\"issue-0001\\"\\ntitle = \\"Test\\"\\nstate = \\"open\\"\\n",\n        )\n        .unwrap();\n        fs::write(root.join(".project/issues/issue-0001/body.md"), "Body\\n").unwrap();\n        fs::write(\n            root.join(".project/remotes/github/remote.toml"),\n            "schema = \\"allodium.remote/v0\\"\\nname = \\"github\\"\\nkind = \\"github\\"\\nrepository = \\"owner/repo\\"\\noutbound = \\"reconcile\\"\\ninbound = \\"archive\\"\\n",\n        )\n        .unwrap();\n        root\n    }\n}\n'
BOARDS_DOC = '# Canonical boards v0\n\nAllodium boards are project-owned filesystem state. GitHub Projects, GitLab boards, Forgejo boards, and future local UIs are projections of that state rather than its authority.\n\nThe v0 model deliberately separates **data** from **presentation**:\n\n```text\n.project/boards/board-0001/\n├── board.toml\n├── fields/\n│   ├── status.toml\n│   └── target-date.toml\n├── items/\n│   ├── issue-0010.toml\n│   └── issue-0011.toml\n└── views/\n    ├── development.toml\n    └── roadmap.toml\n```\n\nEvery authoritative artifact is an ordinary TOML file. No database, Git ref, provider object, or Allodium executable is required to inspect or edit the board.\n\n## Board identity\n\n`board.toml` owns the board\'s project-level identity:\n\n```toml\nschema = "allodium.board/v0"\nid = "board-0001"\ntitle = "Allodium development"\ndescription = "Dogfood board for active Allodium work."\n```\n\nThe `id` must match the containing directory.\n\n## Fields\n\nFields are typed project-owned metadata definitions. v0 supports:\n\n- `text`\n- `number`\n- `date`\n- `single_select`\n\nA single-select field owns stable option IDs:\n\n```toml\nschema = "allodium.board-field/v0"\nid = "status"\nname = "Status"\nkind = "single_select"\n\n[[options]]\nid = "active"\nname = "Active"\n\n[[options]]\nid = "blocked"\nname = "Blocked"\n```\n\nItems store `active` or `blocked`, not the display label. Renaming `Blocked` therefore does not silently rewrite item identity.\n\nOnly single-select fields may declare options. Dates are strict ISO 8601 calendar dates (`YYYY-MM-DD`).\n\n## Items\n\nAn item is membership of an existing canonical Allodium object in a board:\n\n```toml\nschema = "allodium.board-item/v0"\nobject = "issue-0011"\n\n[values]\nstatus = "active"\ntarget-date = "2026-10-01"\n```\n\nThe filename stem must equal the canonical object ID. v0 accepts objects from canonical families Allodium already owns, initially issues and reviews. A provider DraftIssue is not a canonical Allodium issue merely because GitHub Projects can contain it.\n\nValues must reference declared fields and conform to their types.\n\n## Views\n\nViews are presentation metadata over board data:\n\n```toml\nschema = "allodium.board-view/v0"\nid = "development"\nname = "Development"\nlayout = "board"\ngroup_by = "status"\n```\n\nv0 layouts are:\n\n- `table`\n- `board`\n- `roadmap`\n\nA board view requires `group_by`. Its visible columns are the grouped field values. **Columns are not canonical objects.**\n\nA roadmap view requires at least one of `start_field` or `end_field`, and those references must point at canonical date fields.\n\nThis distinction is intentional. The board\'s items and values remain the same when a user switches among table, kanban, and roadmap presentations.\n\n## Validation invariants\n\nAllodium rejects:\n\n- board IDs that do not match their directory;\n- field or view IDs that do not match filename stems;\n- unsupported field or view kinds;\n- duplicate field, view, or single-select option IDs;\n- single-select fields without options;\n- options on non-single-select fields;\n- board items whose filename and canonical object differ;\n- board items referencing missing canonical issues/reviews;\n- duplicate membership of the same canonical object in one board;\n- values referencing unknown fields;\n- values incompatible with their field type;\n- single-select values that are not declared option IDs;\n- view field references that do not exist;\n- board views without a grouping field;\n- roadmap date references that are not date fields.\n\n## GitHub Projects boundary\n\nGitHub\'s current Projects model is a flexible collection of items, fields, and views scoped to a user or organization. A GitHub board view is itself a presentation over Project fields; its columns do not need to become Allodium\'s ontology.\n\nThe GitHub adapter will therefore keep provider-specific identity under `.project/remotes/github/`, including:\n\n- Project node ID/number and URL;\n- owner authority and whether it is a user or organization;\n- Project item node IDs;\n- field and option/iteration node IDs;\n- view node IDs.\n\nGitHub Project DraftIssues remain provider-scoped unless explicitly promoted into a canonical Allodium object.\n\nGitHub also documents a distinct authentication boundary: repository Actions `GITHUB_TOKEN` cannot access Projects. A later adapter increment must use a separately authorized GitHub App or personal access token, keep that credential outside `.project/`, and surface missing authority as a non-mutating capability requirement instead of blocking unrelated repository reconciliation.\n\n## v0 scope\n\nThis first increment is intentionally canonical-only. It establishes executable filesystem semantics before provider mapping, observation, planning, or mutation exists. That ordering is part of the sovereignty model: GitHub ProjectV2 should adapt to Allodium\'s project state, not define it.\n'
DOGFOOD = {'.project/boards/board-0001/board.toml': 'schema = "allodium.board/v0"\nid = "board-0001"\ntitle = "Allodium development"\ndescription = "Dogfood board for active Allodium work."\n', '.project/boards/board-0001/fields/status.toml': 'schema = "allodium.board-field/v0"\nid = "status"\nname = "Status"\nkind = "single_select"\n\n[[options]]\nid = "queued"\nname = "Queued"\n\n[[options]]\nid = "active"\nname = "Active"\n\n[[options]]\nid = "blocked"\nname = "Blocked"\n\n[[options]]\nid = "done"\nname = "Done"\n', '.project/boards/board-0001/fields/target-date.toml': 'schema = "allodium.board-field/v0"\nid = "target-date"\nname = "Target date"\nkind = "date"\n', '.project/boards/board-0001/items/issue-0010.toml': 'schema = "allodium.board-item/v0"\nobject = "issue-0010"\n\n[values]\nstatus = "blocked"\n', '.project/boards/board-0001/items/issue-0011.toml': 'schema = "allodium.board-item/v0"\nobject = "issue-0011"\n\n[values]\nstatus = "active"\n', '.project/boards/board-0001/views/development.toml': 'schema = "allodium.board-view/v0"\nid = "development"\nname = "Development"\nlayout = "board"\ngroup_by = "status"\n', '.project/boards/board-0001/views/roadmap.toml': 'schema = "allodium.board-view/v0"\nid = "roadmap"\nname = "Roadmap"\nlayout = "roadmap"\nend_field = "target-date"\n'}
