def write_text(path_str, content):
    path = Path(path_str)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content)

write_text("crates/allodium-core/src/board.rs", BOARD_RS)
write_text("docs/boards-v0.md", BOARDS_DOC)

lib_path = Path("crates/allodium-core/src/lib.rs")
