if "pub mod board;\n" not in lib:
    lib = lib.replace("pub mod discussion;\n", "pub mod board;\npub mod discussion;\n", 1)
if "board::validate_boards(root, &mut report);\n" not in lib:
    lib = lib.replace(
        "    discussion::validate_discussions(root, &mut report);\n",
        "    board::validate_boards(root, &mut report);\n    discussion::validate_discussions(root, &mut report);\n",
        1,
    )
lib_path.write_text(lib)

