fixtures = Path("crates/allodium-core/tests/fixtures")
for name, files in (("valid-board", VALID_FIXTURE), ("invalid-board-value", INVALID_FIXTURE)):
    target = fixtures / name
    if target.exists():
        shutil.rmtree(target)
    shutil.copytree(fixtures / "valid-minimal", target)
    for relative, content in files.items():
        write_text(str(target / relative), content)

